#[allow(clippy::needless_lifetimes)]
impl<'a> VariationRegionList<'a> {
    /// The data this table's offsets are measured from.
    pub fn offset_data(&self) -> Bytes<'a> {
        self.data
    }

    /// The number of variation axes for this font. This must be the
    /// same number as axisCount in the 'fvar' table.
    pub fn axis_count(&self) -> u16 {
        let range = self.axis_count_byte_range();
        self.data.read_at(range.start).unwrap()
    }

    /// The number of variation region tables in the variation region
    /// list. Must be less than 32,768.
    pub fn region_count(&self) -> u16 {
        let range = self.region_count_byte_range();
        self.data.read_at(range.start).unwrap()
    }

    /// Array of variation regions.
    pub fn variation_regions(&self) -> Array<'a, VariationRegion<'a>> {
        let range = self.variation_regions_byte_range();
        {
            let region_count = self.region_count();
            Array::of_computed_or_empty(
                self.data,
                range.start,
                transforms::to_usize(transforms::to_usize(region_count)),
                self.axis_count(),
            )
        }
    }

    pub fn axis_count_byte_range(&self) -> Range<usize> {
        let start = 0;
        let end = start + u16::RAW_BYTE_LEN;
        start..end
    }

    pub fn region_count_byte_range(&self) -> Range<usize> {
        let start = self.axis_count_byte_range().end;
        let end = start + u16::RAW_BYTE_LEN;
        start..end
    }

    pub fn variation_regions_byte_range(&self) -> Range<usize> {
        let region_count = self.region_count();
        let start = self.region_count_byte_range().end;
        let end = start
            + (transforms::to_usize(region_count)).saturating_mul(
                <VariationRegion as ComputedSize>::computed_size(self.axis_count()),
            );
        start..end
    }
}

/// The [VariationRegion](https://learn.microsoft.com/en-us/typography/opentype/spec/otvarcommonformats#variation-regions) record
#[derive(Clone, Copy)]
pub struct VariationRegion<'a> {
    /// The enclosing table's data: what this record's offsets are
    /// measured from.
    parent: Bytes<'a>,
    /// This record's position within `parent`.
    pos: usize,
    args: u16,
}

impl ComputedSize for VariationRegion<'_> {
    type Args = u16;

    #[allow(unused_variables)]
    fn computed_size(args: u16) -> usize {
        let axis_count = args;
        let _ = &args;
        0usize.saturating_add(
            (transforms::to_usize(axis_count)).saturating_mul(RegionAxisCoordinates::RAW_BYTE_LEN),
        )
    }
}

#[allow(clippy::needless_lifetimes)]
impl<'a> VariationRegion<'a> {
    /// Locates the record at `pos` bytes into `parent`.
    ///
    /// Performs no reads.
    #[inline]
    pub fn at(parent: Bytes<'a>, pos: usize, args: u16) -> Self {
        Self { parent, pos, args }
    }

    /// The data this record's offsets are measured from.
    pub fn offset_data(&self) -> Bytes<'a> {
        self.parent
    }

    pub fn axis_count(&self) -> u16 {
        self.args
    }

    /// Array of region axis coordinates records, in the order of axes
    /// given in the 'fvar' table.
    pub fn region_axes(&self) -> &'a [RegionAxisCoordinates] {
        let range = self.region_axes_byte_range();
        self.parent.read_array(range).unwrap_or_default()
    }

    pub fn region_axes_byte_range(&self) -> Range<usize> {
        let axis_count = self.axis_count();
        let start = self.pos;
        let end = start
            + (transforms::to_usize(axis_count))
                .saturating_mul(RegionAxisCoordinates::RAW_BYTE_LEN);
        start..end
    }
}

