#[cfg(feature = "sanitize")]
impl<'a> Sanitize<'a> for ItemVariationStore<'a> {
    const TYPE_NAME: &'static str = "ItemVariationStore";
    fn sanitize_in(&self, ctx: &mut SanitizeContext) {
        if !ctx.enter_table("ItemVariationStore", self.data) {
            return;
        }
        if self.item_variation_data_offsets_byte_range().end > self.data.len() {
            ctx.check_extent("format", self.format_byte_range(), self.data);
            ctx.check_extent(
                "variation_region_list_offset",
                self.variation_region_list_offset_byte_range(),
                self.data,
            );
            ctx.check_extent(
                "item_variation_data_count",
                self.item_variation_data_count_byte_range(),
                self.data,
            );
            ctx.check_extent(
                "item_variation_data_offsets",
                self.item_variation_data_offsets_byte_range(),
                self.data,
            );
        }
        {
            let target = self.variation_region_list();
            ctx.check_offset(
                "variation_region_list_offset",
                self.variation_region_list_offset().to_u32(),
                target.is_some(),
                false,
            );
            if let Some(target) = target {
                ctx.enter_field("variation_region_list_offset");
                target.sanitize_in(ctx);
                ctx.exit_field();
            }
        }
        ctx.enter_field("item_variation_data_offsets");
        {
            let targets = self.item_variation_data();
            let budget = ctx.element_budget(targets.len());
            for (i, target) in targets.iter().enumerate().take(budget) {
                if ctx.is_done() {
                    break;
                }
                ctx.enter_index(i);
                match target {
                    Some(target) => target.sanitize_in(ctx),
                    None => ctx.report(Problem::NullOffset),
                }
                ctx.exit_index();
            }
        }
        ctx.exit_field();
        ctx.exit_table();
    }
}

#[cfg(feature = "fast_sanitize")]
impl<'a> FastSanitize<'a> for ItemVariationStore<'a> {
    fn fast_sanitize_in(&self, ctx: &mut FastSanitizeContext) -> bool {
        if !ctx.enter(self.data, <Self as Table<'a>>::MIN_SIZE) {
            return false;
        }
        if self.item_variation_data_offsets_byte_range().end > self.data.len() {
            return false;
        }
        {
            let Some(target) = self.variation_region_list() else {
                return false;
            };
            if !target.fast_sanitize_in(ctx) {
                return false;
            }
        }
        {
            let targets = self.item_variation_data();
            let budget = ctx.element_budget(targets.len());
            for target in targets.iter().take(budget) {
                let Some(target) = target else { continue };
                if !target.fast_sanitize_in(ctx) {
                    return false;
                }
            }
        }
        ctx.exit();
        true
    }
}

